  /\ getr R (reg 29) = Z_to_bv 64 159 /\ getr R (reg 30) = Z_to_bv 64 240 /\ getr R (reg 31) = Z_to_bv 64 144.
Lemma vconst_keep R R' S e : vconst R S e -> (forall k, In k VC -> getr R' (reg k) = getr R (reg k)) -> vconst R' S e.
